"""The model: fixed weights, and the reference decoder that defines the right output. Do not edit this file.

A token's feature is ``tanh(E[token] @ W)``. The context at a position is the sum of the features before it, each
weighted by ``DECAY`` to the power of its distance. The next token is the argmax of ``context @ U``.
"""

import math
import random

VOCAB = 64
DIM = 32
DECAY = 0.9

_rng = random.Random(0)
E = [[_rng.uniform(-1, 1) for _ in range(DIM)] for _ in range(VOCAB)]
W = [[_rng.uniform(-0.3, 0.3) for _ in range(DIM)] for _ in range(DIM)]
U = [[_rng.uniform(-1, 1) for _ in range(VOCAB)] for _ in range(DIM)]


def reference(prompt: list[int], max_new_tokens: int) -> list[int]:
    """Return the ``max_new_tokens`` tokens that greedy decoding appends to ``prompt``."""
    tokens = list(prompt)
    for _ in range(max_new_tokens):
        context = [0.0] * DIM
        for distance, token in enumerate(reversed(tokens)):
            weight = DECAY**distance
            for j in range(DIM):
                context[j] += weight * math.tanh(sum(E[token][k] * W[k][j] for k in range(DIM)))
        logits = [sum(context[k] * U[k][v] for k in range(DIM)) for v in range(VOCAB)]
        tokens.append(max(range(VOCAB), key=logits.__getitem__))
    return tokens[len(prompt) :]
